69	    public void assignCustomerCode(int sequence) {
70	        this.customerCode = getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
71	    }
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getEmail() {
77	        return this.email;
78	    }
79	
80	    /** Store the email lower-cased so it is persisted and returned normalised. */
81	    public void setEmail(String email) {
82	        this.email = (email == null) ? null : email.toLowerCase();
83	    }
84	
85	    public LocalDate getRegistrationDate() {
86	        return this.registrationDate;
87	    }
88	
89	    public void setRegistrationDate(LocalDate registrationDate) {
90	        this.registrationDate = registrationDate;
91	    }
92	
93	    /** Default a missing registration date to the server's current date on create. */
94	    @PrePersist
95	    protected void ensureRegistrationDate() {
96	        if (this.registrationDate == null) {
97	            this.registrationDate = LocalDate.now();
98	        }
99	    }
100	
101	    public String getAddress() {
102	        return this.address;
103	    }
104	
105	    public void setAddress(String address) {
106	        this.address = address;
107	    }
108	
109	    public String getCity() {
110	        return this.city;
111	    }
112	
113	    public void setCity(String city) {
114	        this.city = city;
115	    }
116	
