118	        return this.telephone;
119	    }
120	
121	    public void setTelephone(String telephone) {
122	        this.telephone = telephone;
123	    }
124	
125	    protected Set<Pet> getPetsInternal() {
126	        if (this.pets == null) {
127	            this.pets = new HashSet<>();
128	        }
129	        return this.pets;
